module secded_ecc #(
    parameter integer DATA_W = 16,
    localparam integer PARITY_W = (DATA_W <= 4) ? 3 : (DATA_W <= 11) ? 4
                                 : (DATA_W <= 26) ? 5 : 6
) (
    input  logic [DATA_W-1:0]          enc_data,
    output logic [DATA_W+PARITY_W:0]   enc_code,
    input  logic [DATA_W+PARITY_W:0]   dec_code,
    output logic [DATA_W-1:0]          dec_data,
    output logic                       corrected,
    output logic                       uncorrectable
);
    localparam integer H = DATA_W + PARITY_W;

    // Encoder
    always_comb begin
        integer p, k, idx;
        logic par;
        enc_code = '0;
        idx = 0;
        for (p = 1; p <= H; p = p + 1) begin
            if ((p & (p - 1)) != 0) begin
                enc_code[p-1] = enc_data[idx];
                idx = idx + 1;
            end
        end
        for (k = 0; k < PARITY_W; k = k + 1) begin
            par = 1'b0;
            for (p = 1; p <= H; p = p + 1) begin
                if (((p >> k) & 1) != 0) par = par ^ enc_code[p-1];
            end
            enc_code[(1 << k) - 1] = par;
        end
        par = 1'b0;
        for (p = 0; p < H; p = p + 1) par = par ^ enc_code[p];
        enc_code[H] = par;
    end

    // Decoder
    always_comb begin
        integer p, k, idx;
        logic [PARITY_W-1:0] s;
        logic odd;
        logic [H-1:0] c;
        c = dec_code[H-1:0];
        odd = ^dec_code;
        s = '0;
        for (k = 0; k < PARITY_W; k = k + 1) begin
            for (p = 1; p <= H; p = p + 1) begin
                if (((p >> k) & 1) != 0) s[k] = s[k] ^ dec_code[p-1];
            end
        end
        corrected = 1'b0;
        uncorrectable = 1'b0;
        if (odd) begin
            if (s <= H) begin
                corrected = 1'b1;
                if (s != 0) c[s-1] = ~c[s-1];
            end else begin
                uncorrectable = 1'b1;
            end
        end else if (s != 0) begin
            uncorrectable = 1'b1;
        end
        dec_data = '0;
        idx = 0;
        for (p = 1; p <= H; p = p + 1) begin
            if ((p & (p - 1)) != 0) begin
                dec_data[idx] = c[p-1];
                idx = idx + 1;
            end
        end
    end
endmodule

module secded_ecc #(
    parameter integer DATA_W = 16,
    localparam integer PARITY_W = (DATA_W <= 4) ? 3 : (DATA_W <= 11) ? 4
                                 : (DATA_W <= 26) ? 5 : 6
) (
    input  logic [DATA_W-1:0]          enc_data,
    output logic [DATA_W+PARITY_W:0]   enc_code,
    input  logic [DATA_W+PARITY_W:0]   dec_code,
    output logic [DATA_W-1:0]          dec_data,
    output logic                       corrected,
    output logic                       uncorrectable
);
    localparam integer H = DATA_W + PARITY_W;

    // Encoder
    always_comb begin
        logic [H-1:0] h;
        integer di;
        h = '0;
        di = 0;
        for (int p = 1; p <= H; p++) begin
            if ((p & (p - 1)) != 0) begin
                h[p-1] = enc_data[di];
                di = di + 1;
            end
        end
        for (int k = 0; k < PARITY_W; k++) begin
            logic c;
            c = 1'b0;
            for (int p = 1; p <= H; p++) begin
                if (((p >> k) & 1) != 0) c = c ^ h[p-1];
            end
            h[(1<<k)-1] = c;
        end
        enc_code = {^h, h};
    end

    // Decoder
    always_comb begin
        logic [H-1:0] r;
        logic [PARITY_W-1:0] syn;
        logic odd;
        integer di;
        logic flip;
        r = dec_code[H-1:0];
        odd = ^dec_code;
        syn = '0;
        for (int k = 0; k < PARITY_W; k++) begin
            for (int p = 1; p <= H; p++) begin
                if (((p >> k) & 1) != 0) syn[k] = syn[k] ^ r[p-1];
            end
        end
        flip = odd && (syn != 0) && (int'(syn) <= H);
        corrected = odd && ((syn == 0) || (int'(syn) <= H));
        uncorrectable = (!odd && (syn != 0)) || (odd && (int'(syn) > H));
        if (flip) r[int'(syn)-1] = ~r[int'(syn)-1];
        dec_data = '0;
        di = 0;
        for (int p = 1; p <= H; p++) begin
            if ((p & (p - 1)) != 0) begin
                dec_data[di] = r[p-1];
                di = di + 1;
            end
        end
    end
endmodule

module secded_ecc #(
    parameter integer DATA_W = 16,
    localparam integer PARITY_W = (DATA_W <= 4) ? 3 : (DATA_W <= 11) ? 4
                                 : (DATA_W <= 26) ? 5 : 6
) (
    input  logic [DATA_W-1:0]          enc_data,
    output logic [DATA_W+PARITY_W:0]   enc_code,
    input  logic [DATA_W+PARITY_W:0]   dec_code,
    output logic [DATA_W-1:0]          dec_data,
    output logic                       corrected,
    output logic                       uncorrectable
);
    localparam integer H = DATA_W + PARITY_W;

    // Encoder
    always_comb begin
        logic [H:1] cw;
        logic       par;
        integer     idx;
        cw  = '0;
        idx = 0;
        for (int p = 1; p <= H; p++) begin
            if ((p & (p - 1)) != 0) begin
                cw[p] = enc_data[idx];
                idx   = idx + 1;
            end
        end
        for (int k = 0; k < PARITY_W; k++) begin
            par = 1'b0;
            for (int p = 1; p <= H; p++) begin
                if (((p >> k) & 1) != 0) par = par ^ cw[p];
            end
            cw[1 << k] = par;
        end
        enc_code[H-1:0] = cw[H:1];
        enc_code[H]     = ^cw;
    end

    // Decoder
    always_comb begin
        logic [PARITY_W-1:0] syn;
        logic                odd;
        logic [H:1]          rx;
        logic                inrange;
        integer              idx;
        rx  = dec_code[H-1:0];
        odd = ^dec_code;
        syn = '0;
        for (int k = 0; k < PARITY_W; k++) begin
            for (int p = 1; p <= H; p++) begin
                if (((p >> k) & 1) != 0) syn[k] = syn[k] ^ rx[p];
            end
        end
        inrange = (int'(syn) <= H);
        corrected     = odd && inrange;
        uncorrectable = (!odd && (syn != '0)) || (odd && !inrange);
        if (odd && (syn != '0) && inrange)
            rx[int'(syn)] = ~rx[int'(syn)];
        dec_data = '0;
        idx = 0;
        for (int p = 1; p <= H; p++) begin
            if ((p & (p - 1)) != 0) begin
                dec_data[idx] = rx[p];
                idx = idx + 1;
            end
        end
    end
endmodule

module gearbox_16to12 #(
    parameter integer UNIT_W = 4
) (
    input  logic                clk,
    input  logic                rst,
    input  logic                in_valid,
    output logic                in_ready,
    input  logic [4*UNIT_W-1:0] in_data,
    output logic                out_valid,
    input  logic                out_ready,
    output logic [3*UNIT_W-1:0] out_data
);
    logic [UNIT_W-1:0] buf_q [8];
    logic [3:0] n;

    logic       ot, it;
    logic [3:0] nrem;

    assign out_valid = (n >= 4'd3);
    assign ot        = out_valid && out_ready;
    assign nrem      = ot ? (n - 4'd3) : n;
    assign in_ready  = !rst && (nrem <= 4'd4);
    assign it        = in_valid && in_ready;

    always_comb begin
        out_data = '0;
        if (out_valid) begin
            out_data = {buf_q[2], buf_q[1], buf_q[0]};
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            n <= 4'd0;
            for (int i = 0; i < 8; i++) buf_q[i] <= '0;
        end else begin
            for (int i = 0; i < 8; i++) begin
                logic [UNIT_W-1:0] s;
                int j;
                if (ot) s = (i + 3 < 8) ? buf_q[(i + 3) % 8] : '0;
                else    s = buf_q[i];
                j = i - int'(nrem);
                if (it && j >= 0 && j < 4)
                    buf_q[i] <= in_data[(j & 3) * UNIT_W +: UNIT_W];
                else
                    buf_q[i] <= s;
            end
            n <= nrem + (it ? 4'd4 : 4'd0);
        end
    end
endmodule

module gearbox_16to12 #(
    parameter integer UNIT_W = 4
) (
    input  logic                clk,
    input  logic                rst,
    input  logic                in_valid,
    output logic                in_ready,
    input  logic [4*UNIT_W-1:0] in_data,
    output logic                out_valid,
    input  logic                out_ready,
    output logic [3*UNIT_W-1:0] out_data
);

    logic [UNIT_W-1:0] buffer [0:7];
    logic [3:0]        cnt;

    logic              out_fire;
    logic              in_fire;
    logic [3:0]        m;
    logic [UNIT_W-1:0] tmp [0:7];
    logic [UNIT_W-1:0] nxt [0:7];

    always_comb begin
        out_valid = (cnt >= 4'd3);
        out_fire  = out_valid && out_ready;
        m         = out_fire ? (cnt - 4'd3) : cnt;
        in_ready  = !rst && (m <= 4'd4);
        in_fire   = in_valid && in_ready;

        for (int i = 0; i < 8; i++) begin
            if (out_fire) begin
                if (i + 3 < 8) tmp[i] = buffer[(i + 3) & 7];
                else           tmp[i] = '0;
            end else begin
                tmp[i] = buffer[i];
            end
        end

        for (int i = 0; i < 8; i++) begin
            nxt[i] = tmp[i];
            for (int j = 0; j < 4; j++) begin
                if (in_fire && (4'(i) == m + 4'(j)))
                    nxt[i] = in_data[j*UNIT_W +: UNIT_W];
            end
        end

        if (out_valid)
            out_data = {buffer[2], buffer[1], buffer[0]};
        else
            out_data = '0;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            cnt <= 4'd0;
            for (int i = 0; i < 8; i++) buffer[i] <= '0;
        end else begin
            cnt <= m + (in_fire ? 4'd4 : 4'd0);
            for (int i = 0; i < 8; i++) buffer[i] <= nxt[i];
        end
    end

endmodule

module gearbox_16to12 #(
    parameter integer UNIT_W = 4
) (
    input  logic                clk,
    input  logic                rst,
    input  logic                in_valid,
    output logic                in_ready,
    input  logic [4*UNIT_W-1:0] in_data,
    output logic                out_valid,
    input  logic                out_ready,
    output logic [3*UNIT_W-1:0] out_data
);
    localparam integer BW = 8*UNIT_W;

    logic [BW-1:0] buf_q, buf_shift, buf_next;
    logic [3:0]    n_q, m, n_next;
    logic          out_fire, in_fire;

    assign out_valid = (n_q >= 4'd3);
    assign out_fire  = out_valid && out_ready;
    assign m         = out_fire ? (n_q - 4'd3) : n_q;
    assign in_ready  = !rst && (m <= 4'd4);
    assign in_fire   = in_valid && in_ready;
    assign out_data  = out_valid ? buf_q[3*UNIT_W-1:0] : '0;

    always_comb begin
        buf_shift = out_fire ? (buf_q >> (3*UNIT_W)) : buf_q;
        buf_next  = buf_shift;
        n_next    = m;
        if (in_fire) begin
            buf_next = buf_shift | (BW'(in_data) << (m * UNIT_W));
            n_next   = m + 4'd4;
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            buf_q <= '0;
            n_q   <= 4'd0;
        end else begin
            buf_q <= buf_next;
            n_q   <= n_next;
        end
    end
endmodule

module async_fifo #(
    parameter int W = 8,
    parameter int DEPTH = 8
) (
    input  logic         wr_clk,
    input  logic         rd_clk,
    input  logic         rst,
    input  logic         wr_en,
    input  logic [W-1:0] din,
    output logic         full,
    input  logic         rd_en,
    output logic [W-1:0] dout,
    output logic         empty
);

    localparam int AW = $clog2(DEPTH);
    localparam logic [AW:0] MASK = (AW+1)'((1 << AW) | (1 << (AW-1)));

    logic [W-1:0] mem [0:DEPTH-1];

    // write domain
    logic [AW:0] wptr, wgray;
    (* ASYNC_REG = "TRUE" *) logic [AW:0] rq1, rq2;

    // read domain
    logic [AW:0] rptr, rgray;
    (* ASYNC_REG = "TRUE" *) logic [AW:0] wq1, wq2;

    logic [AW:0] wnext, wnext_g;
    logic [AW:0] rnext, rnext_g;
    logic        do_wr, do_rd;

    assign do_wr   = wr_en && !full;
    assign wnext   = wptr + (AW+1)'(do_wr);
    assign wnext_g = wnext ^ (wnext >> 1);

    assign do_rd   = rd_en && !empty;
    assign rnext   = rptr + (AW+1)'(do_rd);
    assign rnext_g = rnext ^ (rnext >> 1);

    always_ff @(posedge wr_clk) begin
        if (rst) begin
            wptr  <= '0;
            wgray <= '0;
            rq1   <= '0;
            rq2   <= '0;
            full  <= 1'b0;
        end else begin
            rq1   <= rgray;
            rq2   <= rq1;
            wptr  <= wnext;
            wgray <= wnext_g;
            full  <= (wnext_g == (rq2 ^ MASK));
            if (do_wr) mem[wptr[AW-1:0]] <= din;
        end
    end

    always_ff @(posedge rd_clk) begin
        if (rst) begin
            rptr  <= '0;
            rgray <= '0;
            wq1   <= '0;
            wq2   <= '0;
            empty <= 1'b1;
            dout  <= '0;
        end else begin
            wq1   <= wgray;
            wq2   <= wq1;
            rptr  <= rnext;
            rgray <= rnext_g;
            empty <= (rnext_g == wq2);
            if (do_rd) dout <= mem[rptr[AW-1:0]];
        end
    end

endmodule

module async_fifo #(
    parameter int W = 8,
    parameter int DEPTH = 8
) (
    input  logic         wr_clk,
    input  logic         rd_clk,
    input  logic         rst,
    input  logic         wr_en,
    input  logic [W-1:0] din,
    output logic         full,
    input  logic         rd_en,
    output logic [W-1:0] dout,
    output logic         empty
);
    localparam int AW = $clog2(DEPTH);

    logic [W-1:0] mem [0:DEPTH-1];

    // write domain
    logic [AW:0] wptr, wgray;
    (* ASYNC_REG = "TRUE" *) logic [AW:0] rg_s1, rg_s2;   // read gray synced into wr_clk

    // read domain
    logic [AW:0] rptr, rgray;
    (* ASYNC_REG = "TRUE" *) logic [AW:0] wg_s1, wg_s2;   // write gray synced into rd_clk

    function automatic logic [AW:0] g2b(input logic [AW:0] g);
        logic [AW:0] b;
        b[AW] = g[AW];
        for (int i = AW-1; i >= 0; i--) b[i] = b[i+1] ^ g[i];
        return b;
    endfunction

    function automatic logic [AW:0] b2g(input logic [AW:0] b);
        return b ^ (b >> 1);
    endfunction

    logic        wr_ok, rd_ok;
    logic [AW:0] wnext, rnext, rbin_sync;

    assign wr_ok     = wr_en & ~full;
    assign rd_ok     = rd_en & ~empty;
    assign wnext     = wptr + {{AW{1'b0}}, wr_ok};
    assign rnext     = rptr + {{AW{1'b0}}, rd_ok};
    assign rbin_sync = g2b(rg_s2);

    always_ff @(posedge wr_clk) begin
        if (rst) begin
            wptr  <= '0;
            wgray <= '0;
            rg_s1 <= '0;
            rg_s2 <= '0;
            full  <= 1'b0;
        end else begin
            if (wr_ok) mem[wptr[AW-1:0]] <= din;
            wptr  <= wnext;
            wgray <= b2g(wnext);
            rg_s1 <= rgray;
            rg_s2 <= rg_s1;
            full  <= (wnext == {~rbin_sync[AW], rbin_sync[AW-1:0]});
        end
    end

    always_ff @(posedge rd_clk) begin
        if (rst) begin
            rptr  <= '0;
            rgray <= '0;
            wg_s1 <= '0;
            wg_s2 <= '0;
            empty <= 1'b1;
            dout  <= '0;
        end else begin
            if (rd_ok) dout <= mem[rptr[AW-1:0]];
            rptr  <= rnext;
            rgray <= b2g(rnext);
            wg_s1 <= wgray;
            wg_s2 <= wg_s1;
            empty <= (b2g(rnext) == wg_s2);
        end
    end
endmodule

module async_fifo #(
    parameter int W = 8,
    parameter int DEPTH = 8
) (
    input  logic         wr_clk,
    input  logic         rd_clk,
    input  logic         rst,
    input  logic         wr_en,
    input  logic [W-1:0] din,
    output logic         full,
    input  logic         rd_en,
    output logic [W-1:0] dout,
    output logic         empty
);
    localparam int AW = $clog2(DEPTH);
    localparam int PW = AW + 1;
    localparam logic [PW-1:0] TOP2 = PW'(3) << (PW-2);

    logic [W-1:0] mem [0:DEPTH-1];

    // write domain
    logic [PW-1:0] wptr, wgray;
    (* ASYNC_REG = "TRUE" *) logic [PW-1:0] rq1, rq2;
    // read domain
    logic [PW-1:0] rptr, rgray;
    (* ASYNC_REG = "TRUE" *) logic [PW-1:0] wq1, wq2;

    logic [PW-1:0] wnext, wgnext, rnext, rgnext;

    assign wnext  = wptr + PW'(wr_en && !full);
    assign wgnext = wnext ^ (wnext >> 1);
    assign rnext  = rptr + PW'(rd_en && !empty);
    assign rgnext = rnext ^ (rnext >> 1);

    always_ff @(posedge wr_clk) begin
        if (rst) begin
            wptr  <= '0;
            wgray <= '0;
            rq1   <= '0;
            rq2   <= '0;
            full  <= 1'b0;
        end else begin
            rq1 <= rgray;
            rq2 <= rq1;
            if (wr_en && !full)
                mem[wptr[AW-1:0]] <= din;
            wptr  <= wnext;
            wgray <= wgnext;
            full  <= (wgnext == (rq2 ^ TOP2));
        end
    end

    always_ff @(posedge rd_clk) begin
        if (rst) begin
            rptr  <= '0;
            rgray <= '0;
            wq1   <= '0;
            wq2   <= '0;
            empty <= 1'b1;
            dout  <= '0;
        end else begin
            wq1 <= wgray;
            wq2 <= wq1;
            if (rd_en && !empty)
                dout <= mem[rptr[AW-1:0]];
            rptr  <= rnext;
            rgray <= rgnext;
            empty <= (rgnext == wq2);
        end
    end
endmodule

module axi4_burst_slave #(
    parameter int ADDR_W = 8,
    parameter int ID_W   = 2,
    parameter int LEN_W  = 8
) (
    input  logic              clk,
    input  logic              rst,

    input  logic [ID_W-1:0]   s_axi_awid,
    input  logic [ADDR_W-1:0] s_axi_awaddr,
    input  logic [LEN_W-1:0]  s_axi_awlen,
    input  logic [2:0]        s_axi_awsize,
    input  logic [1:0]        s_axi_awburst,
    input  logic              s_axi_awlock,
    input  logic [3:0]        s_axi_awcache,
    input  logic [2:0]        s_axi_awprot,
    input  logic [3:0]        s_axi_awqos,
    input  logic [3:0]        s_axi_awregion,
    input  logic              s_axi_awvalid,
    output logic              s_axi_awready,

    input  logic [31:0]       s_axi_wdata,
    input  logic [3:0]        s_axi_wstrb,
    input  logic              s_axi_wlast,
    input  logic              s_axi_wvalid,
    output logic              s_axi_wready,

    output logic [ID_W-1:0]   s_axi_bid,
    output logic [1:0]        s_axi_bresp,
    output logic              s_axi_bvalid,
    input  logic              s_axi_bready,

    input  logic [ID_W-1:0]   s_axi_arid,
    input  logic [ADDR_W-1:0] s_axi_araddr,
    input  logic [LEN_W-1:0]  s_axi_arlen,
    input  logic [2:0]        s_axi_arsize,
    input  logic [1:0]        s_axi_arburst,
    input  logic              s_axi_arlock,
    input  logic [3:0]        s_axi_arcache,
    input  logic [2:0]        s_axi_arprot,
    input  logic [3:0]        s_axi_arqos,
    input  logic [3:0]        s_axi_arregion,
    input  logic              s_axi_arvalid,
    output logic              s_axi_arready,

    output logic [ID_W-1:0]   s_axi_rid,
    output logic [31:0]       s_axi_rdata,
    output logic [1:0]        s_axi_rresp,
    output logic              s_axi_rlast,
    output logic              s_axi_rvalid,
    input  logic              s_axi_rready
);
    localparam int SW = ADDR_W + LEN_W + 3;
    localparam int NW = 1 << (ADDR_W - 2);

    logic [31:0] mem [0:NW-1];

    // write state
    logic              wbusy;
    logic [ID_W-1:0]   awid_q;
    logic [ADDR_W-1:0] waddr;
    logic [LEN_W-1:0]  wcnt;
    logic              wlegal;
    logic              wmis;

    // read state
    logic [ADDR_W-1:0] raddr;
    logic [LEN_W-1:0]  rcnt;
    logic              rlegal;

    assign s_axi_awready = !rst && !wbusy && !s_axi_bvalid;
    assign s_axi_wready  = !rst && wbusy;
    assign s_axi_arready = !rst && !s_axi_rvalid;

    wire aw_hs = s_axi_awvalid && s_axi_awready;
    wire w_hs  = s_axi_wvalid  && s_axi_wready;
    wire ar_hs = s_axi_arvalid && s_axi_arready;
    wire r_hs  = s_axi_rvalid  && s_axi_rready;

    logic [SW-1:0] aw_sum, ar_sum;
    assign aw_sum = SW'(s_axi_awaddr) + {{(SW-LEN_W-2){1'b0}}, s_axi_awlen, 2'b00};
    assign ar_sum = SW'(s_axi_araddr) + {{(SW-LEN_W-2){1'b0}}, s_axi_arlen, 2'b00};

    wire aw_legal = (s_axi_awsize == 3'd2) && (s_axi_awburst == 2'b01) &&
                    !s_axi_awlock && (s_axi_awaddr[1:0] == 2'b00) &&
                    (aw_sum[SW-1:ADDR_W] == '0);
    wire ar_legal = (s_axi_arsize == 3'd2) && (s_axi_arburst == 2'b01) &&
                    !s_axi_arlock && (s_axi_araddr[1:0] == 2'b00) &&
                    (ar_sum[SW-1:ADDR_W] == '0);

    wire w_bad  = (s_axi_wlast != (wcnt == '0));
    wire [ADDR_W-1:0] rnext = raddr + ADDR_W'(4);

    always_ff @(posedge clk) begin
        if (rst) begin
            for (int i = 0; i < NW; i++) mem[i] <= 32'd0;
            wbusy        <= 1'b0;
            awid_q       <= '0;
            waddr        <= '0;
            wcnt         <= '0;
            wlegal       <= 1'b0;
            wmis         <= 1'b0;
            s_axi_bvalid <= 1'b0;
            s_axi_bid    <= '0;
            s_axi_bresp  <= 2'b00;
            raddr        <= '0;
            rcnt         <= '0;
            rlegal       <= 1'b0;
            s_axi_rvalid <= 1'b0;
            s_axi_rid    <= '0;
            s_axi_rresp  <= 2'b00;
            s_axi_rlast  <= 1'b0;
            s_axi_rdata  <= 32'd0;
        end else begin
            // ---------------- write ----------------
            if (s_axi_bvalid && s_axi_bready) s_axi_bvalid <= 1'b0;

            if (aw_hs) begin
                wbusy  <= 1'b1;
                awid_q <= s_axi_awid;
                waddr  <= s_axi_awaddr;
                wcnt   <= s_axi_awlen;
                wlegal <= aw_legal;
                wmis   <= 1'b0;
            end

            if (w_hs) begin
                if (wlegal) begin
                    for (int i = 0; i < 4; i++)
                        if (s_axi_wstrb[i])
                            mem[waddr[ADDR_W-1:2]][8*i +: 8] <= s_axi_wdata[8*i +: 8];
                end
                if (wcnt == '0) begin
                    wbusy        <= 1'b0;
                    s_axi_bvalid <= 1'b1;
                    s_axi_bid    <= awid_q;
                    s_axi_bresp  <= (wlegal && !wmis && !w_bad) ? 2'b00 : 2'b10;
                end else begin
                    wcnt  <= wcnt - 1'b1;
                    waddr <= waddr + ADDR_W'(4);
                    wmis  <= wmis | w_bad;
                end
            end

            // ---------------- read ----------------
            if (ar_hs) begin
                raddr        <= s_axi_araddr;
                rcnt         <= s_axi_arlen;
                rlegal       <= ar_legal;
                s_axi_rvalid <= 1'b1;
                s_axi_rid    <= s_axi_arid;
                s_axi_rresp  <= ar_legal ? 2'b00 : 2'b10;
                s_axi_rlast  <= (s_axi_arlen == '0);
                s_axi_rdata  <= ar_legal ? mem[s_axi_araddr[ADDR_W-1:2]] : 32'd0;
            end else if (r_hs) begin
                if (s_axi_rlast) begin
                    s_axi_rvalid <= 1'b0;
                end else begin
                    raddr       <= rnext;
                    rcnt        <= rcnt - 1'b1;
                    s_axi_rlast <= (rcnt == LEN_W'(1));
                    s_axi_rdata <= rlegal ? mem[rnext[ADDR_W-1:2]] : 32'd0;
                end
            end
        end
    end

    wire unused = &{1'b0, s_axi_awcache, s_axi_awprot, s_axi_awqos, s_axi_awregion,
                    s_axi_arcache, s_axi_arprot, s_axi_arqos, s_axi_arregion};
endmodule

module axi4_burst_slave #(
    parameter int ADDR_W = 8,
    parameter int ID_W   = 2,
    parameter int LEN_W  = 8
) (
    input  logic              clk,
    input  logic              rst,

    input  logic [ID_W-1:0]   s_axi_awid,
    input  logic [ADDR_W-1:0] s_axi_awaddr,
    input  logic [LEN_W-1:0]  s_axi_awlen,
    input  logic [2:0]        s_axi_awsize,
    input  logic [1:0]        s_axi_awburst,
    input  logic              s_axi_awlock,
    input  logic [3:0]        s_axi_awcache,
    input  logic [2:0]        s_axi_awprot,
    input  logic [3:0]        s_axi_awqos,
    input  logic [3:0]        s_axi_awregion,
    input  logic              s_axi_awvalid,
    output logic              s_axi_awready,

    input  logic [31:0]       s_axi_wdata,
    input  logic [3:0]        s_axi_wstrb,
    input  logic              s_axi_wlast,
    input  logic              s_axi_wvalid,
    output logic              s_axi_wready,

    output logic [ID_W-1:0]   s_axi_bid,
    output logic [1:0]        s_axi_bresp,
    output logic              s_axi_bvalid,
    input  logic              s_axi_bready,

    input  logic [ID_W-1:0]   s_axi_arid,
    input  logic [ADDR_W-1:0] s_axi_araddr,
    input  logic [LEN_W-1:0]  s_axi_arlen,
    input  logic [2:0]        s_axi_arsize,
    input  logic [1:0]        s_axi_arburst,
    input  logic              s_axi_arlock,
    input  logic [3:0]        s_axi_arcache,
    input  logic [2:0]        s_axi_arprot,
    input  logic [3:0]        s_axi_arqos,
    input  logic [3:0]        s_axi_arregion,
    input  logic              s_axi_arvalid,
    output logic              s_axi_arready,

    output logic [ID_W-1:0]   s_axi_rid,
    output logic [31:0]       s_axi_rdata,
    output logic [1:0]        s_axi_rresp,
    output logic              s_axi_rlast,
    output logic              s_axi_rvalid,
    input  logic              s_axi_rready
);
    localparam int SW = ADDR_W + LEN_W + 3;
    localparam int NW = 2**(ADDR_W-2);

    logic [31:0] mem [0:NW-1];

    // write state
    logic              wbusy;
    logic [ID_W-1:0]   awid_q;
    logic [ADDR_W-1:0] waddr_q;
    logic [LEN_W-1:0]  wlen_q, wcnt_q;
    logic              wlegal_q, wmm_q;

    // read state
    logic [ADDR_W-1:0] raddr_q;
    logic [LEN_W-1:0]  rrem_q;
    logic              rlegal_q;

    // legality
    logic [SW-1:0] aw_sum, ar_sum;
    logic aw_legal, ar_legal;
    assign aw_sum   = SW'(s_axi_awaddr) + (SW'(s_axi_awlen) << 2);
    assign ar_sum   = SW'(s_axi_araddr) + (SW'(s_axi_arlen) << 2);
    assign aw_legal = (s_axi_awsize == 3'd2) && (s_axi_awburst == 2'b01) && !s_axi_awlock &&
                      (s_axi_awaddr[1:0] == 2'b00) && ((aw_sum >> ADDR_W) == 0);
    assign ar_legal = (s_axi_arsize == 3'd2) && (s_axi_arburst == 2'b01) && !s_axi_arlock &&
                      (s_axi_araddr[1:0] == 2'b00) && ((ar_sum >> ADDR_W) == 0);

    assign s_axi_awready = !rst && !wbusy && !s_axi_bvalid;
    assign s_axi_wready  = !rst && wbusy;
    assign s_axi_arready = !rst && !s_axi_rvalid;

    logic aw_hs, w_hs, ar_hs, r_hs;
    assign aw_hs = s_axi_awvalid && s_axi_awready;
    assign w_hs  = s_axi_wvalid && s_axi_wready;
    assign ar_hs = s_axi_arvalid && s_axi_arready;
    assign r_hs  = s_axi_rvalid && s_axi_rready;

    logic w_last_exp, w_mm_next;
    assign w_last_exp = (wcnt_q == wlen_q);
    assign w_mm_next  = wmm_q || (s_axi_wlast != w_last_exp);

    logic [ADDR_W-1:0] raddr_next;
    assign raddr_next = raddr_q + ADDR_W'(4);

    always_ff @(posedge clk) begin
        if (rst) begin
            for (int i = 0; i < NW; i++) mem[i] <= 32'd0;
            wbusy        <= 1'b0;
            awid_q       <= '0;
            waddr_q      <= '0;
            wlen_q       <= '0;
            wcnt_q       <= '0;
            wlegal_q     <= 1'b0;
            wmm_q        <= 1'b0;
            s_axi_bvalid <= 1'b0;
            s_axi_bid    <= '0;
            s_axi_bresp  <= 2'b00;
            raddr_q      <= '0;
            rrem_q       <= '0;
            rlegal_q     <= 1'b0;
            s_axi_rvalid <= 1'b0;
            s_axi_rid    <= '0;
            s_axi_rresp  <= 2'b00;
            s_axi_rlast  <= 1'b0;
            s_axi_rdata  <= 32'd0;
        end else begin
            // ---------------- write ----------------
            if (s_axi_bvalid && s_axi_bready) s_axi_bvalid <= 1'b0;

            if (aw_hs) begin
                wbusy    <= 1'b1;
                awid_q   <= s_axi_awid;
                waddr_q  <= s_axi_awaddr;
                wlen_q   <= s_axi_awlen;
                wcnt_q   <= '0;
                wlegal_q <= aw_legal;
                wmm_q    <= 1'b0;
            end

            if (w_hs) begin
                if (wlegal_q) begin
                    for (int i = 0; i < 4; i++)
                        if (s_axi_wstrb[i])
                            mem[waddr_q[ADDR_W-1:2]][8*i +: 8] <= s_axi_wdata[8*i +: 8];
                end
                waddr_q <= waddr_q + ADDR_W'(4);
                wcnt_q  <= wcnt_q + LEN_W'(1);
                wmm_q   <= w_mm_next;
                if (w_last_exp) begin
                    wbusy        <= 1'b0;
                    s_axi_bvalid <= 1'b1;
                    s_axi_bid    <= awid_q;
                    s_axi_bresp  <= (wlegal_q && !w_mm_next) ? 2'b00 : 2'b10;
                end
            end

            // ---------------- read ----------------
            if (ar_hs) begin
                s_axi_rvalid <= 1'b1;
                s_axi_rid    <= s_axi_arid;
                s_axi_rresp  <= ar_legal ? 2'b00 : 2'b10;
                s_axi_rdata  <= ar_legal ? mem[s_axi_araddr[ADDR_W-1:2]] : 32'd0;
                s_axi_rlast  <= (s_axi_arlen == '0);
                raddr_q      <= s_axi_araddr;
                rrem_q       <= s_axi_arlen;
                rlegal_q     <= ar_legal;
            end else if (r_hs) begin
                if (s_axi_rlast) begin
                    s_axi_rvalid <= 1'b0;
                end else begin
                    s_axi_rdata <= rlegal_q ? mem[raddr_next[ADDR_W-1:2]] : 32'd0;
                    raddr_q     <= raddr_next;
                    rrem_q      <= rrem_q - LEN_W'(1);
                    s_axi_rlast <= (rrem_q == LEN_W'(1));
                end
            end
        end
    end

    logic unused;
    assign unused = &{1'b0, s_axi_awcache, s_axi_awprot, s_axi_awqos, s_axi_awregion,
                      s_axi_arcache, s_axi_arprot, s_axi_arqos, s_axi_arregion};
endmodule

module axi4_burst_slave #(
    parameter int ADDR_W = 8,
    parameter int ID_W   = 2,
    parameter int LEN_W  = 8
) (
    input  logic              clk,
    input  logic              rst,

    input  logic [ID_W-1:0]   s_axi_awid,
    input  logic [ADDR_W-1:0] s_axi_awaddr,
    input  logic [LEN_W-1:0]  s_axi_awlen,
    input  logic [2:0]        s_axi_awsize,
    input  logic [1:0]        s_axi_awburst,
    input  logic              s_axi_awlock,
    input  logic [3:0]        s_axi_awcache,
    input  logic [2:0]        s_axi_awprot,
    input  logic [3:0]        s_axi_awqos,
    input  logic [3:0]        s_axi_awregion,
    input  logic              s_axi_awvalid,
    output logic              s_axi_awready,

    input  logic [31:0]       s_axi_wdata,
    input  logic [3:0]        s_axi_wstrb,
    input  logic              s_axi_wlast,
    input  logic              s_axi_wvalid,
    output logic              s_axi_wready,

    output logic [ID_W-1:0]   s_axi_bid,
    output logic [1:0]        s_axi_bresp,
    output logic              s_axi_bvalid,
    input  logic              s_axi_bready,

    input  logic [ID_W-1:0]   s_axi_arid,
    input  logic [ADDR_W-1:0] s_axi_araddr,
    input  logic [LEN_W-1:0]  s_axi_arlen,
    input  logic [2:0]        s_axi_arsize,
    input  logic [1:0]        s_axi_arburst,
    input  logic              s_axi_arlock,
    input  logic [3:0]        s_axi_arcache,
    input  logic [2:0]        s_axi_arprot,
    input  logic [3:0]        s_axi_arqos,
    input  logic [3:0]        s_axi_arregion,
    input  logic              s_axi_arvalid,
    output logic              s_axi_arready,

    output logic [ID_W-1:0]   s_axi_rid,
    output logic [31:0]       s_axi_rdata,
    output logic [1:0]        s_axi_rresp,
    output logic              s_axi_rlast,
    output logic              s_axi_rvalid,
    input  logic              s_axi_rready
);
    localparam int SW = ADDR_W + LEN_W + 3;
    localparam int NW = 2 ** (ADDR_W - 2);

    logic [31:0] mem [0:NW-1];

    // write state
    logic              aw_active;
    logic [ADDR_W-1:0] wr_addr;
    logic [LEN_W-1:0]  wr_cnt;
    logic              wr_legal;
    logic              wr_err;
    logic [ID_W-1:0]   wr_id;

    // read state
    logic [ADDR_W-1:0] rd_addr;
    logic [LEN_W-1:0]  rd_cnt;

    // descriptor legality
    logic [SW-1:0] aw_sum, ar_sum;
    logic aw_legal, ar_legal;
    always_comb begin
        aw_sum = SW'(s_axi_awaddr) + (SW'(s_axi_awlen) << 2);
        ar_sum = SW'(s_axi_araddr) + (SW'(s_axi_arlen) << 2);
        aw_legal = (s_axi_awsize == 3'd2) && (s_axi_awburst == 2'b01) && !s_axi_awlock
                   && (s_axi_awaddr[1:0] == 2'b00) && ((aw_sum >> ADDR_W) == 0);
        ar_legal = (s_axi_arsize == 3'd2) && (s_axi_arburst == 2'b01) && !s_axi_arlock
                   && (s_axi_araddr[1:0] == 2'b00) && ((ar_sum >> ADDR_W) == 0);
    end

    assign s_axi_awready = !rst && !aw_active && !s_axi_bvalid;
    assign s_axi_wready  = !rst && aw_active;
    assign s_axi_arready = !rst && !s_axi_rvalid;

    wire aw_hs = s_axi_awvalid && s_axi_awready;
    wire w_hs  = s_axi_wvalid  && s_axi_wready;
    wire ar_hs = s_axi_arvalid && s_axi_arready;
    wire r_hs  = s_axi_rvalid  && s_axi_rready;
    wire b_hs  = s_axi_bvalid  && s_axi_bready;

    wire w_mismatch = (s_axi_wlast != (wr_cnt == '0));
    wire wr_err_n   = wr_err | w_mismatch;

    wire [ADDR_W-3:0] wr_idx = wr_addr[ADDR_W-1:2];
    wire [ADDR_W-3:0] rd_idx = rd_addr[ADDR_W-1:2];
    wire [ADDR_W-3:0] ar_idx = s_axi_araddr[ADDR_W-1:2];

    always_ff @(posedge clk) begin
        if (rst) begin
            for (int i = 0; i < NW; i++) mem[i] <= 32'd0;
            aw_active    <= 1'b0;
            wr_addr      <= '0;
            wr_cnt       <= '0;
            wr_legal     <= 1'b0;
            wr_err       <= 1'b0;
            wr_id        <= '0;
            s_axi_bvalid <= 1'b0;
            s_axi_bid    <= '0;
            s_axi_bresp  <= 2'b00;
            rd_addr      <= '0;
            rd_cnt       <= '0;
            s_axi_rvalid <= 1'b0;
            s_axi_rid    <= '0;
            s_axi_rresp  <= 2'b00;
            s_axi_rlast  <= 1'b0;
            s_axi_rdata  <= 32'd0;
        end else begin
            // ---------------- write ----------------
            if (b_hs) s_axi_bvalid <= 1'b0;

            if (aw_hs) begin
                aw_active <= 1'b1;
                wr_addr   <= s_axi_awaddr;
                wr_cnt    <= s_axi_awlen;
                wr_legal  <= aw_legal;
                wr_err    <= 1'b0;
                wr_id     <= s_axi_awid;
            end

            if (w_hs) begin
                if (wr_legal) begin
                    for (int i = 0; i < 4; i++)
                        if (s_axi_wstrb[i]) mem[wr_idx][8*i +: 8] <= s_axi_wdata[8*i +: 8];
                end
                wr_err  <= wr_err_n;
                wr_addr <= wr_addr + ADDR_W'(4);
                if (wr_cnt == '0) begin
                    aw_active    <= 1'b0;
                    s_axi_bvalid <= 1'b1;
                    s_axi_bid    <= wr_id;
                    s_axi_bresp  <= (wr_legal && !wr_err_n) ? 2'b00 : 2'b10;
                end else begin
                    wr_cnt <= wr_cnt - 1'b1;
                end
            end

            // ---------------- read ----------------
            if (ar_hs) begin
                s_axi_rvalid <= 1'b1;
                s_axi_rid    <= s_axi_arid;
                s_axi_rresp  <= ar_legal ? 2'b00 : 2'b10;
                s_axi_rlast  <= (s_axi_arlen == '0);
                s_axi_rdata  <= ar_legal ? mem[ar_idx] : 32'd0;
                rd_addr      <= s_axi_araddr + ADDR_W'(4);
                rd_cnt       <= s_axi_arlen;
            end else if (r_hs) begin
                if (s_axi_rlast) begin
                    s_axi_rvalid <= 1'b0;
                end else begin
                    s_axi_rlast <= (rd_cnt == LEN_W'(1));
                    s_axi_rdata <= (s_axi_rresp == 2'b00) ? mem[rd_idx] : 32'd0;
                    rd_addr     <= rd_addr + ADDR_W'(4);
                    rd_cnt      <= rd_cnt - 1'b1;
                end
            end
        end
    end

    wire unused = &{1'b0, s_axi_awcache, s_axi_awprot, s_axi_awqos, s_axi_awregion,
                    s_axi_arcache, s_axi_arprot, s_axi_arqos, s_axi_arregion};
endmodule

module cache_controller #(
    parameter int DATA_W = 32,
    parameter int TAG_W = 5,
    parameter int INDEX_W = 2
) (
    input  logic                     clk,
    input  logic                     rst,
    input  logic                     inv_valid,
    output logic                     inv_ready,
    input  logic                     cpu_req_valid,
    output logic                     cpu_req_ready,
    input  logic [TAG_W+INDEX_W:0]   cpu_req_addr,
    output logic                     cpu_rsp_valid,
    input  logic                     cpu_rsp_ready,
    output logic [DATA_W-1:0]        cpu_rsp_data,
    output logic                     mem_req_valid,
    input  logic                     mem_req_ready,
    output logic [TAG_W+INDEX_W-1:0] mem_req_addr,
    input  logic                     mem_rsp_valid,
    output logic                     mem_rsp_ready,
    input  logic [2*DATA_W-1:0]      mem_rsp_data
);
    localparam int LINES = 2**INDEX_W;

    typedef enum logic [1:0] {S_IDLE, S_MREQ, S_REFILL, S_RSP} state_t;
    state_t state;

    logic [LINES-1:0]        vld;
    logic [TAG_W-1:0]        tags  [LINES];
    logic [2*DATA_W-1:0]     lines [LINES];

    logic [TAG_W+INDEX_W:0]  saved_addr;
    logic [DATA_W-1:0]       rsp_q;

    wire [INDEX_W-1:0] req_idx = cpu_req_addr[INDEX_W:1];
    wire [TAG_W-1:0]   req_tag = cpu_req_addr[TAG_W+INDEX_W:INDEX_W+1];
    wire               req_off = cpu_req_addr[0];
    wire [INDEX_W-1:0] sv_idx  = saved_addr[INDEX_W:1];

    wire hit = vld[req_idx] && (tags[req_idx] == req_tag);
    wire [2*DATA_W-1:0] hit_line = lines[req_idx];

    assign inv_ready     = (state == S_IDLE) && !rst;
    assign cpu_req_ready = (state == S_IDLE) && !inv_valid && !rst;
    assign mem_req_valid = (state == S_MREQ) && !rst;
    assign mem_req_addr  = mem_req_valid ? saved_addr[TAG_W+INDEX_W:1] : '0;
    assign mem_rsp_ready = (state == S_REFILL) && !rst;
    assign cpu_rsp_valid = (state == S_RSP) && !rst;
    assign cpu_rsp_data  = cpu_rsp_valid ? rsp_q : '0;

    always_ff @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE;
            vld   <= '0;
        end else begin
            case (state)
                S_IDLE: begin
                    if (inv_valid) begin
                        vld <= '0;
                    end else if (cpu_req_valid) begin
                        if (hit) begin
                            rsp_q <= req_off ? hit_line[2*DATA_W-1:DATA_W]
                                             : hit_line[DATA_W-1:0];
                            state <= S_RSP;
                        end else begin
                            saved_addr <= cpu_req_addr;
                            state <= S_MREQ;
                        end
                    end
                end
                S_MREQ: begin
                    if (mem_req_ready) state <= S_REFILL;
                end
                S_REFILL: begin
                    if (mem_rsp_valid) begin
                        lines[sv_idx] <= mem_rsp_data;
                        tags[sv_idx]  <= saved_addr[TAG_W+INDEX_W:INDEX_W+1];
                        vld[sv_idx]   <= 1'b1;
                        rsp_q <= saved_addr[0] ? mem_rsp_data[2*DATA_W-1:DATA_W]
                                               : mem_rsp_data[DATA_W-1:0];
                        state <= S_RSP;
                    end
                end
                S_RSP: begin
                    if (cpu_rsp_ready) state <= S_IDLE;
                end
                default: state <= S_IDLE;
            endcase
        end
    end
endmodule

module cache_controller #(
    parameter int DATA_W = 32,
    parameter int TAG_W = 5,
    parameter int INDEX_W = 2
) (
    input  logic                     clk,
    input  logic                     rst,
    input  logic                     inv_valid,
    output logic                     inv_ready,
    input  logic                     cpu_req_valid,
    output logic                     cpu_req_ready,
    input  logic [TAG_W+INDEX_W:0]   cpu_req_addr,
    output logic                     cpu_rsp_valid,
    input  logic                     cpu_rsp_ready,
    output logic [DATA_W-1:0]        cpu_rsp_data,
    output logic                     mem_req_valid,
    input  logic                     mem_req_ready,
    output logic [TAG_W+INDEX_W-1:0] mem_req_addr,
    input  logic                     mem_rsp_valid,
    output logic                     mem_rsp_ready,
    input  logic [2*DATA_W-1:0]      mem_rsp_data
);
    localparam int LINES = 2**INDEX_W;

    typedef enum logic [1:0] {S_IDLE, S_MREQ, S_REFILL, S_RESP} state_t;
    state_t state;

    logic [2*DATA_W-1:0]  data_arr [LINES];
    logic [TAG_W-1:0]     tag_arr  [LINES];
    logic [LINES-1:0]     valid_arr;

    logic [TAG_W+INDEX_W:0] addr_q;
    logic [DATA_W-1:0]      rdata_q;

    wire [INDEX_W-1:0] req_idx = cpu_req_addr[INDEX_W:1];
    wire [TAG_W-1:0]   req_tag = cpu_req_addr[TAG_W+INDEX_W:INDEX_W+1];
    wire [INDEX_W-1:0] sav_idx = addr_q[INDEX_W:1];

    wire idle = (state == S_IDLE) && !rst;

    assign inv_ready     = idle;
    assign cpu_req_ready = idle && !inv_valid;
    assign mem_req_valid = (state == S_MREQ) && !rst;
    assign mem_rsp_ready = (state == S_REFILL) && !rst;
    assign cpu_rsp_valid = (state == S_RESP) && !rst;
    assign mem_req_addr  = mem_req_valid ? addr_q[TAG_W+INDEX_W:1] : '0;
    assign cpu_rsp_data  = cpu_rsp_valid ? rdata_q : '0;

    wire [2*DATA_W-1:0] line_rd = data_arr[req_idx];
    wire hit = valid_arr[req_idx] && (tag_arr[req_idx] == req_tag);

    always_ff @(posedge clk) begin
        if (rst) begin
            state     <= S_IDLE;
            valid_arr <= '0;
        end else begin
            case (state)
                S_IDLE: begin
                    if (inv_valid) begin
                        valid_arr <= '0;
                    end else if (cpu_req_valid) begin
                        addr_q <= cpu_req_addr;
                        if (hit) begin
                            rdata_q <= cpu_req_addr[0] ? line_rd[2*DATA_W-1:DATA_W]
                                                       : line_rd[DATA_W-1:0];
                            state <= S_RESP;
                        end else begin
                            state <= S_MREQ;
                        end
                    end
                end
                S_MREQ: begin
                    if (mem_req_ready) state <= S_REFILL;
                end
                S_REFILL: begin
                    if (mem_rsp_valid) begin
                        data_arr[sav_idx] <= mem_rsp_data;
                        tag_arr[sav_idx]  <= addr_q[TAG_W+INDEX_W:INDEX_W+1];
                        valid_arr[sav_idx] <= 1'b1;
                        rdata_q <= addr_q[0] ? mem_rsp_data[2*DATA_W-1:DATA_W]
                                             : mem_rsp_data[DATA_W-1:0];
                        state <= S_RESP;
                    end
                end
                S_RESP: begin
                    if (cpu_rsp_ready) state <= S_IDLE;
                end
                default: state <= S_IDLE;
            endcase
        end
    end
endmodule

module cache_controller #(
    parameter int DATA_W = 32,
    parameter int TAG_W = 5,
    parameter int INDEX_W = 2
) (
    input  logic                     clk,
    input  logic                     rst,
    input  logic                     inv_valid,
    output logic                     inv_ready,
    input  logic                     cpu_req_valid,
    output logic                     cpu_req_ready,
    input  logic [TAG_W+INDEX_W:0]   cpu_req_addr,
    output logic                     cpu_rsp_valid,
    input  logic                     cpu_rsp_ready,
    output logic [DATA_W-1:0]        cpu_rsp_data,
    output logic                     mem_req_valid,
    input  logic                     mem_req_ready,
    output logic [TAG_W+INDEX_W-1:0] mem_req_addr,
    input  logic                     mem_rsp_valid,
    output logic                     mem_rsp_ready,
    input  logic [2*DATA_W-1:0]      mem_rsp_data
);
    localparam int LINES = 2**INDEX_W;

    typedef enum logic [1:0] {S_IDLE, S_MREQ, S_REFILL, S_RSP} state_t;
    state_t state;

    logic [LINES-1:0]        valid;
    logic [TAG_W-1:0]        tags  [LINES];
    logic [2*DATA_W-1:0]     lines [LINES];

    logic [TAG_W+INDEX_W:0]  saved_addr;
    logic [DATA_W-1:0]       rsp_q;

    wire [INDEX_W-1:0] req_idx = cpu_req_addr[INDEX_W:1];
    wire [TAG_W-1:0]   req_tag = cpu_req_addr[TAG_W+INDEX_W:INDEX_W+1];
    wire [INDEX_W-1:0] sv_idx  = saved_addr[INDEX_W:1];
    wire [TAG_W-1:0]   sv_tag  = saved_addr[TAG_W+INDEX_W:INDEX_W+1];

    wire idle = (state == S_IDLE) && !rst;

    assign inv_ready     = idle;
    assign cpu_req_ready = idle && !inv_valid;
    assign mem_req_valid = (state == S_MREQ) && !rst;
    assign mem_rsp_ready = (state == S_REFILL) && !rst;
    assign cpu_rsp_valid = (state == S_RSP) && !rst;
    assign mem_req_addr  = mem_req_valid ? saved_addr[TAG_W+INDEX_W:1] : '0;
    assign cpu_rsp_data  = cpu_rsp_valid ? rsp_q : '0;

    wire hit = valid[req_idx] && (tags[req_idx] == req_tag);
    wire [2*DATA_W-1:0] hit_line = lines[req_idx];

    always_ff @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE;
            valid <= '0;
        end else begin
            case (state)
                S_IDLE: begin
                    if (inv_valid) begin
                        valid <= '0;
                    end else if (cpu_req_valid) begin
                        if (hit) begin
                            rsp_q <= cpu_req_addr[0] ? hit_line[2*DATA_W-1:DATA_W]
                                                     : hit_line[DATA_W-1:0];
                            state <= S_RSP;
                        end else begin
                            saved_addr <= cpu_req_addr;
                            state <= S_MREQ;
                        end
                    end
                end
                S_MREQ: begin
                    if (mem_req_ready) state <= S_REFILL;
                end
                S_REFILL: begin
                    if (mem_rsp_valid) begin
                        lines[sv_idx] <= mem_rsp_data;
                        tags[sv_idx]  <= sv_tag;
                        valid[sv_idx] <= 1'b1;
                        rsp_q <= saved_addr[0] ? mem_rsp_data[2*DATA_W-1:DATA_W]
                                               : mem_rsp_data[DATA_W-1:0];
                        state <= S_RSP;
                    end
                end
                S_RSP: begin
                    if (cpu_rsp_ready) state <= S_IDLE;
                end
                default: state <= S_IDLE;
            endcase
        end
    end
endmodule

module packet_checksum #(
    parameter integer BYTE_W = 8
) (
    input  logic                  clk,
    input  logic                  rst,
    input  logic                  in_valid,
    output logic                  in_ready,
    input  logic [BYTE_W-1:0]     in_data,
    input  logic                  in_last,
    output logic                  out_valid,
    input  logic                  out_ready,
    output logic [2*BYTE_W-1:0]  out_checksum
);
    localparam integer W = 2*BYTE_W;

    logic [W-1:0]      sum;
    logic [BYTE_W-1:0] hi;
    logic              have_hi;

    logic [W-1:0] word;
    logic [W:0]   s_ext;
    logic [W-1:0] folded;
    logic         accept;

    assign in_ready = !rst && (!in_last || !out_valid || out_ready);
    assign accept   = in_valid && in_ready;

    assign word   = have_hi ? {hi, in_data} : {in_data, {BYTE_W{1'b0}}};
    assign s_ext  = {1'b0, sum} + {1'b0, word};
    assign folded = s_ext[W-1:0] + {{(W-1){1'b0}}, s_ext[W]};

    always_ff @(posedge clk) begin
        if (rst) begin
            sum          <= '0;
            hi           <= '0;
            have_hi      <= 1'b0;
            out_valid    <= 1'b0;
            out_checksum <= '0;
        end else begin
            // output transfer clears slot unless replaced below
            if (out_valid && out_ready) begin
                out_valid    <= 1'b0;
                out_checksum <= '0;
            end
            if (accept) begin
                if (in_last) begin
                    out_valid    <= 1'b1;
                    out_checksum <= ~folded;
                    sum          <= '0;
                    have_hi      <= 1'b0;
                end else if (have_hi) begin
                    sum     <= folded;
                    have_hi <= 1'b0;
                end else begin
                    hi      <= in_data;
                    have_hi <= 1'b1;
                end
            end
        end
    end
endmodule

module packet_checksum #(
    parameter integer BYTE_W = 8
) (
    input  logic                  clk,
    input  logic                  rst,
    input  logic                  in_valid,
    output logic                  in_ready,
