    always_comb begin
        if (have_hi) word = {hi, in_data};
        else         word = {in_data, {BYTE_W{1'b0}}};
        wide      = {1'b0, sum} + {1'b0, word};
        folded    = wide[W2-1:0] + {{(W2-1){1'b0}}, wide[W2]};
        word_done = have_hi || in_last;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            sum          <= '0;
            hi           <= '0;
            have_hi      <= 1'b0;
            out_valid    <= 1'b0;
            out_checksum <= '0;
        end else begin
            if (out_valid && out_ready) begin
                out_valid    <= 1'b0;
                out_checksum <= '0;
            end
            if (accept) begin
                if (in_last) begin
                    out_valid    <= 1'b1;
                    out_checksum <= ~folded;
                    sum          <= '0;
                    have_hi      <= 1'b0;
                end else if (have_hi) begin
                    sum     <= folded;
                    have_hi <= 1'b0;
                end else begin
                    hi      <= in_data;
                    have_hi <= 1'b1;
                end
            end
        end
    end
endmodule

