module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [2:0] src_q [5];
    logic [2:0] cur_q [5];

    logic [2:0] dest [5];
    logic [4:0] gv;
    logic [2:0] gsel [5];

    function automatic logic [2:0] succ(input logic [2:0] s);
        return (s == 3'd4) ? 3'd0 : s + 3'd1;
    endfunction

    always_comb begin
        logic [1:0] dx, dy;
        logic [2:0] start, idx;
        logic       avail, found;

        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F + PAYLOAD_W + 2 +: 2];
            dy = in_flit[i*F + PAYLOAD_W +: 2];
            if (dx > X)      dest[i] = 3'd2;
            else if (dx < X) dest[i] = 3'd3;
            else if (dy > Y) dest[i] = 3'd0;
            else if (dy < Y) dest[i] = 3'd1;
            else             dest[i] = 3'd4;
        end

        in_ready = 5'b0;
        for (int o = 0; o < 5; o++) begin
            avail = !out_valid[o] || out_ready[o];
            start = (out_valid[o] && out_ready[o]) ? succ(src_q[o]) : cur_q[o];
            found = 1'b0;
            gv[o] = 1'b0;
            gsel[o] = 3'd0;
            idx = start;
            for (int k = 0; k < 5; k++) begin
                if (!found && avail && in_valid[idx] && dest[idx] == 3'(o)) begin
                    found = 1'b1;
                    gv[o] = 1'b1;
                    gsel[o] = idx;
                    in_ready[idx] = !rst;
                end
                idx = succ(idx);
            end
        end
    end

    always_ff @(posedge clk) begin
        for (int o = 0; o < 5; o++) begin
            if (rst) begin
                out_valid[o]       <= 1'b0;
                out_flit[o*F +: F] <= '0;
                cur_q[o]           <= 3'd0;
                src_q[o]           <= 3'd0;
            end else begin
                if (out_valid[o] && out_ready[o])
                    cur_q[o] <= succ(src_q[o]);
                if (!out_valid[o] || out_ready[o]) begin
                    out_valid[o] <= gv[o];
                    if (gv[o]) begin
                        out_flit[o*F +: F] <= in_flit[gsel[o]*F +: F];
                        src_q[o]           <= gsel[o];
                    end else begin
                        out_flit[o*F +: F] <= '0;
                    end
                end
            end
        end
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [4:0]           valid_q = 5'b0;
    logic [5*F-1:0]       flit_q  = '0;
    logic [14:0]          src_q   = 15'b0;   // 3 bits per output
    logic [14:0]          cur_q   = 15'b0;   // 3 bits per output

    logic [14:0]          dest;              // 3 bits per input
    logic [4:0]           gv;
    logic [14:0]          gsel;              // 3 bits per output
    logic [4:0]           rdy;

    assign out_valid = valid_q;
    assign out_flit  = flit_q;
    assign in_ready  = rdy;

    function automatic logic [2:0] succ(input logic [2:0] s);
        return (s == 3'd4) ? 3'd0 : (s + 3'd1);
    endfunction

    always_comb begin
        rdy  = 5'b0;
        gv   = 5'b0;
        gsel = 15'b0;
        dest = 15'b0;

        for (int i = 0; i < 5; i++) begin
            if (in_flit[i*F + PAYLOAD_W + 2 +: 2] > X)
                dest[i*3 +: 3] = 3'd2;
            else if (in_flit[i*F + PAYLOAD_W + 2 +: 2] < X)
                dest[i*3 +: 3] = 3'd3;
            else if (in_flit[i*F + PAYLOAD_W +: 2] > Y)
                dest[i*3 +: 3] = 3'd0;
            else if (in_flit[i*F + PAYLOAD_W +: 2] < Y)
                dest[i*3 +: 3] = 3'd1;
            else
                dest[i*3 +: 3] = 3'd4;
        end

        for (int o = 0; o < 5; o++) begin
            logic [2:0] idx;
            idx = (valid_q[o] && out_ready[o]) ? succ(src_q[o*3 +: 3]) : cur_q[o*3 +: 3];
            for (int k = 0; k < 5; k++) begin
                if (!gv[o] && (!valid_q[o] || out_ready[o]) && in_valid[idx] &&
                    (int'(dest[idx*3 +: 3]) == o)) begin
                    gv[o] = 1'b1;
                    gsel[o*3 +: 3] = idx;
                    rdy[idx] = !rst;
                end
                idx = succ(idx);
            end
        end
    end

    always_ff @(posedge clk) begin
        for (int o = 0; o < 5; o++) begin
            if (rst) begin
                valid_q[o]        <= 1'b0;
                flit_q[o*F +: F]  <= '0;
                cur_q[o*3 +: 3]   <= 3'd0;
                src_q[o*3 +: 3]   <= 3'd0;
            end else begin
                if (valid_q[o] && out_ready[o])
                    cur_q[o*3 +: 3] <= succ(src_q[o*3 +: 3]);
                if (!valid_q[o] || out_ready[o]) begin
                    valid_q[o] <= gv[o];
                    if (gv[o]) begin
                        flit_q[o*F +: F] <= in_flit[gsel[o*3 +: 3]*F +: F];
                        src_q[o*3 +: 3]  <= gsel[o*3 +: 3];
                    end else begin
                        flit_q[o*F +: F] <= '0;
                    end
                end
            end
        end
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [4:0]           valid_q = 5'b0;
    logic [5*F-1:0]       flit_q  = '0;
    logic [4:0][2:0]      src_q   = '0;
    logic [4:0][2:0]      cur_q   = '0;

    logic [4:0][2:0]      dest;     // per input
    logic [4:0][4:0]      req;      // req[o][i]
    logic [4:0][4:0]      grant;    // grant[o][i]
    logic [4:0][F-1:0]    nflit;    // next flit per output

    assign out_valid = valid_q;
    assign out_flit  = flit_q;

    function automatic logic [2:0] succ(input logic [2:0] s);
        return (s == 3'd4) ? 3'd0 : (s + 3'd1);
    endfunction

    function automatic logic [4:0] arb(input logic [4:0] r,
                                       input logic [2:0] start,
                                       input logic       avail);
        logic [4:0] g;
        logic [2:0] idx;
        logic       found;
        g = 5'b0;
        found = 1'b0;
        idx = start;
        for (int k = 0; k < 5; k++) begin
            if (!found && avail && r[idx]) begin
                g[idx] = 1'b1;
                found = 1'b1;
            end
            idx = succ(idx);
        end
        return g;
    endfunction

    function automatic logic [2:0] enc(input logic [4:0] g);
        logic [2:0] e;
        e = 3'd0;
        if (g[1]) e = 3'd1;
        if (g[2]) e = 3'd2;
        if (g[3]) e = 3'd3;
        if (g[4]) e = 3'd4;
        return e;
    endfunction

    genvar gi, go;
    generate
        for (gi = 0; gi < 5; gi++) begin : g_dest
            wire [1:0] dx = in_flit[gi*F + PAYLOAD_W + 2 +: 2];
            wire [1:0] dy = in_flit[gi*F + PAYLOAD_W +: 2];
            assign dest[gi] = (dx > X) ? 3'd2 :
                              (dx < X) ? 3'd3 :
                              (dy > Y) ? 3'd0 :
                              (dy < Y) ? 3'd1 : 3'd4;
        end

        for (go = 0; go < 5; go++) begin : g_out
            for (gi = 0; gi < 5; gi++) begin : g_req
                assign req[go][gi] = in_valid[gi] && (dest[gi] == 3'(go));
            end

            wire [2:0] start = (valid_q[go] && out_ready[go]) ? succ(src_q[go]) : cur_q[go];
            assign grant[go] = arb(req[go], start, !valid_q[go] || out_ready[go]);

            always_comb begin
                nflit[go] = '0;
                for (int i = 0; i < 5; i++)
                    if (grant[go][i])
                        nflit[go] = nflit[go] | in_flit[i*F +: F];
            end

            always_ff @(posedge clk) begin
                if (rst) begin
                    valid_q[go]       <= 1'b0;
                    flit_q[go*F +: F] <= '0;
                    cur_q[go]         <= 3'd0;
                    src_q[go]         <= 3'd0;
                end else begin
                    if (valid_q[go] && out_ready[go])
                        cur_q[go] <= succ(src_q[go]);
                    if (!valid_q[go] || out_ready[go]) begin
                        valid_q[go]       <= |grant[go];
                        flit_q[go*F +: F] <= nflit[go];
                        if (|grant[go])
                            src_q[go] <= enc(grant[go]);
                    end
                end
            end
        end

        for (gi = 0; gi < 5; gi++) begin : g_rdy
            assign in_ready[gi] = !rst && (grant[0][gi] | grant[1][gi] | grant[2][gi] |
                                           grant[3][gi] | grant[4][gi]);
        end
    endgenerate
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [4:0]   vld;
    logic [F-1:0] slot   [5];
    logic [2:0]   cursor [5];

    logic [4:0]   req [5];       // req[input][output]
    logic [4:0]   acc;           // accept per output
    logic [2:0]   sel_idx [5];
    logic [F-1:0] sel_flit [5];
    logic [4:0]   rdy;

    always_comb begin
        logic [1:0] dx, dy;
        logic [F-1:0] fl;
        logic found;
        int idx;
        logic avail;

        for (int i = 0; i < 5; i++) begin
            fl = in_flit[i*F +: F];
            dx = fl[F-1:F-2];
            dy = fl[F-3:F-4];
            req[i] = 5'b0;
            if (in_valid[i]) begin
                if (dx > X)       req[i][2] = 1'b1;
                else if (dx < X)  req[i][3] = 1'b1;
                else if (dy > Y)  req[i][0] = 1'b1;
                else if (dy < Y)  req[i][1] = 1'b1;
                else              req[i][4] = 1'b1;
            end
        end

        rdy = 5'b0;
        for (int o = 0; o < 5; o++) begin
            acc[o] = 1'b0;
            sel_idx[o] = 3'd0;
            sel_flit[o] = '0;
            found = 1'b0;
            avail = !vld[o] || out_ready[o];
            for (int k = 0; k < 5; k++) begin
                idx = int'(cursor[o]) + k;
                if (idx >= 5) idx = idx - 5;
                if (!found && avail && !rst && req[idx][o]) begin
                    found = 1'b1;
                    acc[o] = 1'b1;
                    sel_idx[o] = 3'(idx);
                    sel_flit[o] = in_flit[idx*F +: F];
                    rdy[idx] = 1'b1;
                end
            end
        end
    end

    assign in_ready = rdy;
    assign out_valid = vld;

    always_comb begin
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = vld[o] ? slot[o] : '0;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            vld <= 5'b0;
            for (int o = 0; o < 5; o++) begin
                slot[o]   <= '0;
                cursor[o] <= 3'd0;
            end
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (acc[o]) begin
                    vld[o]    <= 1'b1;
                    slot[o]   <= sel_flit[o];
                    cursor[o] <= (sel_idx[o] == 3'd4) ? 3'd0 : sel_idx[o] + 3'd1;
                end else if (vld[o] && out_ready[o]) begin
                    vld[o]  <= 1'b0;
                    slot[o] <= '0;
                end
            end
        end
    end
endmodule

