module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [4:0]   v;
    logic [2:0]   src [5];
    logic [2:0]   cur [5];
    logic [F-1:0] dat [5];

    logic [2:0]   rt  [5];
    logic [4:0]   gnt [5];       // gnt[o][i]
    logic [2:0]   sel [5];
    logic [4:0]   found;
    logic [4:0]   drain;
    logic [4:0]   avail;

    function automatic logic [2:0] succ(input logic [2:0] s);
        succ = (s == 3'd4) ? 3'd0 : s + 3'd1;
    endfunction

    always_comb begin
        logic [1:0] dx, dy;
        logic [2:0] start, idx;
        logic [F-1:0] fl;

        for (int i = 0; i < 5; i++) begin
            fl = in_flit[i*F +: F];
            dx = fl[F-1 -: 2];
            dy = fl[F-3 -: 2];
            if (dx > X)       rt[i] = 3'd2;
            else if (dx < X)  rt[i] = 3'd3;
            else if (dy > Y)  rt[i] = 3'd0;
            else if (dy < Y)  rt[i] = 3'd1;
            else              rt[i] = 3'd4;
        end

        for (int o = 0; o < 5; o++) begin
            drain[o] = v[o] & out_ready[o];
            avail[o] = ~v[o] | out_ready[o];
            start    = drain[o] ? succ(src[o]) : cur[o];
            gnt[o]   = 5'b0;
            sel[o]   = 3'd0;
            found[o] = 1'b0;
            for (int k = 0; k < 5; k++) begin
                idx = start + 3'(k);
                if (idx >= 3'd5) idx = idx - 3'd5;
                if (avail[o] && !found[o] && in_valid[idx] && rt[idx] == 3'(o)) begin
                    found[o]      = 1'b1;
                    sel[o]        = idx;
                    gnt[o][idx]   = 1'b1;
                end
            end
        end

        in_ready = 5'b0;
        for (int o = 0; o < 5; o++)
            in_ready = in_ready | gnt[o];
        if (rst) in_ready = 5'b0;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            v <= 5'b0;
            for (int o = 0; o < 5; o++) begin
                src[o] <= 3'd0;
                cur[o] <= 3'd0;
                dat[o] <= '0;
            end
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (drain[o]) cur[o] <= succ(src[o]);
                if (avail[o]) begin
                    if (found[o]) begin
                        v[o]   <= 1'b1;
                        dat[o] <= in_flit[sel[o]*F +: F];
                        src[o] <= sel[o];
                    end else begin
                        v[o]   <= 1'b0;
                        dat[o] <= '0;
                    end
                end
            end
        end
    end

    always_comb begin
        out_valid = v;
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = dat[o];
    end
endmodule

